    [4730] = {n="떠내려온 바다 생물", d="아우버다인에 있는 그웨니스 블리레곤드에게 바다 생물 뼈를 가져가야 합니다."},
    [4731] = {n="떠내려온 바다 거북", d="아우버다인에 있는 그웨니스 블리레곤드에게 이상한 표식이 된 상자를 가져가야 합니다."},
    [4732] = {n="떠내려온 바다 거북", d="아우버다인에 있는 그웨니스 블리레곤드에게 바다 거북 잔해를 가져가야 합니다."},
    [4733] = {n="떠내려온 바다 생물", d="아우버다인에 있는 그웨니스 블리레곤드에게 바다 생물 뼈를 가져가야 합니다."},
    [4740] = {n="현상수배: 먹구렁", d="먹구렁이라는 멀록을 찾아서 처치해야 합니다. 이 괴물은 아우버다인 남쪽, 해안에서 멀록 오두막을 보호하고 있는 것으로 추정됩니다.\n먹구렁을 처치하면 아우버다인에 있는 파수꾼 글린다 날셰에게 보고하십시오.", tgo={{"먹구렁"}}},
    [4761] = {n="툰드리스 윈드위버", d="아우버다인에 있는 툰드리스 윈드위버와 대화하십시오."},
    [4762] = {n="폭포수 강", d="아우버다인 북쪽으로 가서 폭포수 강 가장자리에 있는 첫 번째 폭포에서 물 견본을 채취해야 합니다.\n폭포수 강물 견본을 가지고 아우버다인에 있는 툰드리스 윈드위버에게 돌아가십시오.", objs={"Cliffspring River Waterfall"}},
    [4763] = {n="타락한 검은나무일족", d="아우버다인 달샘의 물로 빈 정화의 그릇을 채우십시오.\n검은나무일족 펄볼그 북부 야영지에서 검은나무일족 과일 견본, 검은나무일족 열매 견본, 검은나무일족 곡식 견본을 모으십시오.\n물과 음식을 한데 섞어 북부 야영지의 폭포수 강에서 가장 가까운 화톳불 근처에 두면 사티로스 타락자를 불러낼 수 있습니다.\n부패의 부적을 손에 넣은 후 아우버다인에 있는 툰드리스 윈드위버에게 가져가십시오.", objs={"사브라시스의 도깨비 가방"}},
    [4811] = {n="붉은 수정", d="어둠의 해안의 동쪽 산맥을 따라 아우버다인 동쪽으로 가서 거대한 붉은 수정을 찾은 다음 아우버다인에 있는 파수꾼 글린다 날셰에게 보고해야 합니다.", objs={"신비한 붉은 수정"}},
    [4812] = {n="수정에 물이 흐르면", d="빈 시험관에 아우버다인의 달샘 물을 채운 후 어둠의해안의 동쪽 산에 있는 붉은 수정을 찾아 조사하십시오.", objs={"아우버다인 달샘"}},
    [4813] = {n="수정 안의 뼈", d="아우버다인에 있는 파수꾼 글린다 날셰에게 알아 낸 사실을 보고해야 합니다."},
    [4842] = {n="이상한 근원", d="도노바 스노우덴의 지시를 따라 탐색을 한 후 되돌아오십시오."},
    [4861] = {n="성난 올빼미야수", d="여명의 설원 남부 <name>역에서 야론 스톤셰이퍼의 야영<name>를 찾아서 부서진 보급품 상자를 되찾아 와야 합니다."},
    [4863] = {n="성난 올빼미야수", d="야론 스톤셰이퍼의 부서진 마차를 찾아야 합니다."},
    [4864] = {n="성난 올빼미야수", d="눈 속에서 야론의 보급품을 회수한 다음, 야론이 찾는 아뮬렛을 훔친 올빼미야수들을 찾아야 합니다.\n여명의 설원, 별똥별 마을에 있는 야론 스톤셰이퍼에게 야론의 보급품과 푸른 깃털달린 아뮬렛을 갖다주어야 합니다.", tgo={{}, {"광기어린 올빼미야수", "달빛 깃든 올빼미야수", "광포한 올빼미야수", "엘룬의 수호자"}}, objs={"야론의 보급품"}},
    [4901] = {n="제단의 수호자", d="엘룬의 제단을 여는 과정에서 란샬라를 보호해야 합니다. 성공하면 루테란 마을에 있는 에렐라스 앰버스카이에게 발견한 내용을 보고해야 합니다."},
    [4902] = {n="엘룬의 올빼미야수", d="다르나서스에 있는 대드루이드 판드랄 스테그헬름과 대화해야 합니다."},
    [4906] = {n="오염의 확산", d="에리단 블루윈드를 위해 비취불꽃 지옥소환사 8명과 배반자 8명, 그리고 요술사 8명과 사바릭을 처단해야 합니다. 임무가 완수되는 대로 에리단에게 돌아가십시오.", tgo={{"비취불꽃의 지옥소환사"}, {"비취불꽃의 배반자"}, {"비취불꽃의 요술사"}, {"사바릭"}}},
    [4971] = {n="시간 문제", d="안돌할 저장고 근처에서 시간의 재배열기를 이용해 시간의 기생충들을 찾아내십시오.\n시간의 기생충 15마리를 처치한 후, 서부 역병지대의 안돌할 여관에 있는 크로미에게 시간의 재배열기를 가져가야 합니다.", tgo={{"시간의 기생충"}}},
    [4984] = {n="야생 동물들의 고통", d="역병에 걸린 늑대 8마리를 처치한 후, 서부 역병지대의 고통의 흉가에 있는 멀그리스 딥리버에게 돌아가야 합니다.", tgo={{"역병에 걸린 늑대"}}},
    [4985] = {n="야생 동물들의 고통", d="오염된 불곰 8마리를 처치한 후, 서부 역병지대의 고통의 흉가에 있는 멀그리스 딥리버에게 돌아가야 합니다.", tgo={{"오염된 불곰"}}},
    [4986] = {n="문자가 새겨진 떡갈나무 가지", d="문자가 새겨진 떡갈나무 가지에 걸린 문자로 미루어볼 때 타우렌 드루이드가 이 가지를 가져가려고 한 장소는 다르나서스에 있는 세나리온 의회입니다. 그곳에서 드루이드를 한 명 찾아 도움을 요청하십시오."},
    [5021] = {n="늦어버린 소포 배달", d="유령 여인의 두서없는 말을 들으니 소포를 전달해야 했던 것 같습니다. 자신의 말이 있던 곳에 소포가 있다고 했는데, 말이 어디 있는지, 그리고 소포를 어디로 전달해야 하는지에 대해서는 이해할 수 없는 말만 늘어놓습니다."},
    [5022] = {n="늦어버린 소포 배달", d="스톰윈드의 왕실 조사원과 대화하여 엠마 펠스톤의 행방을 알아내십시오. 인구조사국 담당자는 보통 스톰윈드 시청에 있습니다."},
    [5048] = {n="착한 엠마", d="스톰윈드에서 올엠마를 찾아 그녀가 엠마 펠스톤인지 확인하십시오. 그녀가 정말 엠마 펠스톤이라면 재니스 펠스톤이 보낸 소포를 원할지도 모릅니다."},
    [5050] = {n="행운의 부적", d="서부 역병지대에 있는 재니스 펠스톤에게 행운의 부적 조각을 되돌려줘야 합니다."},
    [5066] = {n="역병지대 징집령!", d="사령관 아쉬람 발러피스트를 찾아야 합니다. 그의 주둔지는 알터랙 산맥 북쪽의 서리바람 야영지입니다."},
    [5082] = {n="눈사태일족의 위협", d="여명의 설원에 있는 도노바 스노우덴이 눈사태일족 길잡이 8마리, 눈사태일족 보초 8마리, 눈사태일족 토템술사 8마리를 처치해달라고 요청했습니다.", tgo={{"눈사태일족 길잡이"}, {"눈사태일족 보초"}, {"눈사태일족 토템술사"}}},
    [5083] = {n="눈사태일족 화주", d="여명의 설원에 있는 도노바 스노우덴에게 빈 화주 시험관을 갖다주어야 합니다."},
    [5084] = {n="타락에 빠지다", d="악령의 숲 북부에 있는 마른가지일족 펄볼그 야영지에서 단서를 찾아야 합니다."},
    [5085] = {n="신비한 액체", d="발견한 사실을 도노바 스노우덴에게 알려야 합니다."},
    [5092] = {n="통로 확보", d="슬픔의 언덕에 있는 해골 타작꾼 10마리와 걸신들린 구울 10마리를 처치해야 합니다.\n그런 다음 서부 역병지대의 서리바람 야영지에 있는 사령관 아쉬람 발러피스트에게 돌아가십시오.", tgo={{"해골 타작꾼"}, {"걸신들린 구울"}}},
    [5097] = {n="감시탑 공격 준비", d="신호 횃불로 안돌할의 각 탑을 표시해야 합니다. 성공적으로 표시하려면 탑의 입구에 서야 합니다.\n네 개의 감시탑에 모두 표시했으면 신호 횃불을 서부 역병지대의 서리바람 야영지에 있는 사령관 아쉬람 발러피스트에게 가져가십시오.", tgo={{"안돌할 탑 1"}, {"안돌할 탑 2"}, {"안돌할 탑 3"}, {"안돌할 탑 4"}}},
    [5149] = {n="파멜라의 인형", d="파멜라의 인형을 찾아야 합니다."},
    [5152] = {n="말레네 고모", d="안돌할 폐허 남쪽에서 말레네와 대화해야 합니다."},
    [5153] = {n="이상한 역사가", d="조셉의 결혼반지를 크로미에게 가져가야 합니다.", objs={"조셉 레드패스의 기념비"}},
    [5154] = {n="다로우샤이어 연대기", d="안돌할에 있는 다로우샤이어 연대기를 크로미에게 갖다주어야 합니다.", objs={"곰팡이 슨 고서"}},
    [5155] = {n="자에데나르의 힘", d="자에데나르에 가서 자에데나르 사냥개 4마리, 자에데나르 수호병 4명, 자에데나르 숙련사제 6명, 자에데나르 이교도 6명을 처치하고 그레타 모스후프에게 돌아가야 합니다.", tgo={{"자에데나르 사냥개"}, {"자에데나르 수호병"}, {"자에데나르 숙련사제"}, {"자에데나르 이교도"}}},
    [5156] = {n="오염 확인", d="불벼락 골짜기를 탐색하는 동안 혼돈의 불길 2마리와 혼돈의 소산물 2마리를 처치해야 합니다. 분화구를 조사해 아직도 부패한 물이 남아 있는지 확인하고 악령의 숲의 타론 레드페더에게 돌아가야 합니다.", tgo={{"혼돈의 불길"}, {"혼돈의 소산물"}}},
    [5157] = {n="부패한 물 채취", d="빈 수통을 자에데나르 중심부의 달샘으로 가져가서 채운 다음 악령의 숲에 있는 그레타 모스후프에게 가져 가야 합니다.", objs={"오염된 제데나르 달샘"}},
    [5158] = {n="영혼의 도움을 찾아서", d="부패한 달샘 물을 불모의 땅에 있는 이슬렌 워터시어에게 가져 가야 합니다."},
    [5159] = {n="악령의 숲으로 정화된 물 가져가기", d="정화된 달샘 물을 악령의 숲에 있는 그레타 모스후프에게 가져가야 합니다."},
    [5168] = {n="다로우샤이어의 영웅", d="카를린 레드패스에게 다빌의 성서와 레드패스의 방패를 가져가야 합니다.", objs={"다빌의 성서", "레드패스의 방패"}},
    [5181] = {n="다로우샤이어의 악당들", d="희망의 빛 예배당에 있는 카를린 레드패스에게 호르구스의 해골과 부러진 마르두크의 검을 가져가야 합니다.", objs={"호르구스의 해골", "부러진 마르두크의 검"}},
    [5210] = {n="카를린 레드패스", d="동부 역병지대에 있는 카를린 레드패스에게 확장된 다로우샤이어 연대기를 가져가야 합니다."},
    [5211] = {n="다로우샤이어의 병사들", d="15명의 다로우샤이어 주민들의 원혼을 자유롭게 하고 카를린 레드패스에게 돌아가야 합니다.", tgo={{"다로우샤이어 영혼"}}},
    [5215] = {n="스컬지 가마솥", d="서부 역병지대의 서리바람 거점에 있는 대여사제 맥도널과 대화해야 합니다."},
    [5216] = {n="목표: 펠스톤 농장", d="서부 역병지대의 펠스톤 농장으로 가서 그곳에 있는 가마솥군주를 찾아 물리치십시오. 가마솥군주가 가마솥으로 통하는 열쇠를 지니고 있을 수도 있습니다. 빈 펠스톤 농장 병으로 가마솥 안에 있는 독의 견본을 확보해야 합니다.", tgo={{"가마솥군주 창자아귀"}}},
    [5217] = {n="서리바람 야영지로의 귀환", d="서부 역병지대의 서리바람 야영지에 있는 대여사제 맥도널에게 가득 찬 펠스톤 농장 병을 가져가야 합니다."},
    [5219] = {n="목표: 달슨의 눈물", d="서부 역병지대의 달슨의 눈물로 가서 그곳에 있는 가마솥군주를 찾아 물리치고, 그가 지닌 열쇠를 사용해 가마솥에 접근하십시오. 반드시 달슨의 눈물 빈병으로 가마솥 안에 있는 독의 견본을 확보해야 합니다.", tgo={{"가마솥군주 말비니어스"}}},
    [5220] = {n="서리바람 야영지로의 귀환", d="서부 역병지대의 서리바람 야영지에 있는 대여사제 맥도널에게 가득 찬 달슨의 눈물 혼합물을 가져가야 합니다."},
    [5222] = {n="목표: 고통의 흉가", d="서부 역병지대의 고통의 흉가로 가서 그곳에 있는 가마솥군주를 찾아 물리치고, 그가 가진 열쇠를 사용해 가마솥에 접근하십시오. 반드시 고통의 흉가 빈병으로 가마솥 안에 있는 독의 견본을 확보해야 합니다.", tgo={{"가마솥군주 라자르취"}}},
